import 'package:zan/Core/Models/product_model.dart';import 'package:zan/Core/Storage/Remote/api_endpoints.dart';import 'package:zan/Core/Storage/Remote/api_service.dart';import '../../../../../../Core/Models/product_details_model.dart';import '../entities/product_details.dart';class ProductDetailsSources {  static Future<ProductDetailsEntities> getProductDetails(      {required int id}) async {    final response =        await DioHelper.getData(path: "${ApiEndpoints.productDetails}+$id");    if (response != null && response.statusCode == 200) {      final product = ProductDetailsEntities.fromProduct(          ProductDetailsModel.fromJson(response.data["data"]));      return product;    } else {      throw Exception('Failed to load product details');    }  }}